var STALE_MS = 60 * 60 * 1e3;
var staleAfterInWords = () => {
  const hours = STALE_MS / (60 * 60 * 1e3);
  if (hours >= 1) return hours === 1 ? "over an hour" : `over ${hours} hours`;
  return `over ${Math.round(STALE_MS / 6e4)} minutes`;
};

